('67e7f9f0-eb35-5b08-8c5c-735b0a79a784'::uuid,'est','"Triangles, Trigonometry & Similarity"'::jsonb,'medium','mcq','"A child is standing at point C and flying a kite located at point A, 25 ft above the ground. As the child lets out more string, the kite rises to point B, directly above point A. If the angle of elevation changes from 50° to 65°, how much higher, to the nearest foot, is the kite than it was initially?\n[Figure: vertical segment DA = 25 ft, D at ground below A; C on ground; right angle at D; angle at C is 50°.]"'::jsonb,'[{"key":"A","text":"5"},{"key":"B","text":"20"},{"key":"C","text":"21"},{"key":"D","text":"45"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"aist.md","source_sha256":"e9fd07b1d1b86aee4b6b4a657186e8b73bef5b70d0a2a4adb6ffbc2a04e45d42","source_question_id":"AI-46","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Triangles, Trigonometry & Similarity","image":"https://raw.githubusercontent.com/xxx64220-debug/ghoneem-math-portal/main/assets/question-bank/AI-46.png","image_alt":"Original graph, diagram, or table for AI-46","visual_verified":true}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from aist.md (AI-46)."'::jsonb),
('592b64c6-0bb9-5e27-a0ec-a8126b265c34'::uuid,'est','"Rational, Radical, Exponential & Logarithmic Functions"'::jsonb,'medium','mcq','"What are the domain and range for the relation y = (x + 5)/(x − 5)?"'::jsonb,'[{"key":"A","text":"The domain is the set of all real numbers. The range is the set of all real numbers."},{"key":"B","text":"The domain is the set of all real numbers ≠ 5. The range is the set of all real numbers ≠ 1."},{"key":"C","text":"The domain is the set of all real numbers ≠ −5. The range is the set of all real numbers ≠ 1."},{"key":"D","text":"The domain is the set of all real numbers. The range is the set of all real numbers ≠ 5."}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"aist.md","source_sha256":"e9fd07b1d1b86aee4b6b4a657186e8b73bef5b70d0a2a4adb6ffbc2a04e45d42","source_question_id":"AI-47","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Rational, Radical, Exponential & Logarithmic Functions"}'::jsonb,'"B"'::jsonb,'"Source-keyed answer from aist.md (AI-47)."'::jsonb),
('aa214e2b-11c6-59d4-8873-c9082028484c'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Maria''s father is 10 years younger than 3 times Maria''s current age. In 5 years, his age will be 5 years more than 2 times her age. Which equation can be used to find Maria''s current age?"'::jsonb,'[{"key":"A","text":"3x − 5 = 2x + 5"},{"key":"B","text":"3x − 10 = 2x + 15"},{"key":"C","text":"3x − 10 = 2x + 10"},{"key":"D","text":"3x + 15 = 2x + 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"aist.md","source_sha256":"e9fd07b1d1b86aee4b6b4a657186e8b73bef5b70d0a2a4adb6ffbc2a04e45d42","source_question_id":"AI-48","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from aist.md (AI-48)."'::jsonb),
