('e490f866-3336-5bab-8142-ce3a8e2755d0'::uuid,'est','"Algebra Foundations, Equations & Inequalities"'::jsonb,'medium','mcq','"Which of the following is an equation for the line passing through (0, 0) and (4, 3) in the standard (x, y) coordinate plane?"'::jsonb,'[{"key":"A","text":"x − y = 1"},{"key":"B","text":"x + y = 7"},{"key":"C","text":"3x − 4y = 0"},{"key":"D","text":"3x + 4y = 25"},{"key":"E","text":"4x + 3y = 25"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t1.md","source_sha256":"eef682d7d604550f5b03d4515fc8ad2b38118fd3a6267cd26237107865237ce6","source_question_id":"T1-02","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Algebra Foundations, Equations & Inequalities"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t1.md (T1-02)."'::jsonb),
